targets.query:
import "join"

//------------------------------------------------------------
// 1) Периоды для сравнения
//------------------------------------------------------------
periodA_start = time(v: 2025-05-18T12:24:00Z)
periodA_stop  = time(v: 2025-05-18T12:25:00Z)

periodB_start = time(v: 2025-05-18T12:25:00Z)
periodB_stop  = time(v: 2025-05-18T12:35:00Z)

//------------------------------------------------------------
// 2) Функция, строящая метрики
//------------------------------------------------------------
buildMetrics = (raw) => (
    raw
      |> group(columns: ["class", "name", "param_types"])
      |> reduce(
           fn: (r, accumulator) => ({        // ← имя accumulator
               class:  r.class,
               name:   r.name,
               param_types: r.param_types,
               count:  accumulator.count + 1,
               sum_ns: accumulator.sum_ns + float(v: r._value),
               max_ns: if float(v: r._value) > accumulator.max_ns
                         then float(v: r._value)
                         else accumulator.max_ns
           }),
           identity: {class:"", name:"", param_types:"", count:0, sum_ns:0.0, max_ns:0.0}
         )
      |> join.inner(
           right:
             raw
               |> group(columns: ["class", "name", "param_types"])
               |> quantile(q: 0.50, column: "_value", method: "estimate_tdigest")
               |> rename(columns: {_value: "p50_ns"}),
           on: (l,r) => l.class == r.class and l.name == r.name and l.param_types == r.param_types,
           as: (l,r) => ({ l with p50_ns: r.p50_ns })
         )
      |> join.inner(
           right:
             raw
               |> group(columns: ["class", "name", "param_types"])
               |> quantile(q: 0.95, column: "_value", method: "estimate_tdigest")
               |> rename(columns: {_value: "p95_ns"}),
           on: (l,r) => l.class == r.class and l.name == r.name and l.param_types == r.param_types,
           as: (l,r) => ({ l with p95_ns: r.p95_ns })
         )
      |> map(fn:(r)=>({
           class:  r.class,
           name:   r.name,
           param_types: r.param_types,
           avg_ns: if r.count == 0 then 0.0 else r.sum_ns / float(v: r.count),
           count: r.count,
           sum_ns: r.sum_ns,
           max_ns: r.max_ns,
           p50_ns: r.p50_ns,
           p95_ns: r.p95_ns
         }))
)

//------------------------------------------------------------
// 3) Чтение данных и расчёт метрик
//------------------------------------------------------------
rawA =
  from(bucket: "${custom_bucket_name}")
    |> range(start: periodA_start, stop: periodA_stop)
    |> filter(fn:(r)=>r._measurement=="method_timing" and r._field=="duration_ns")

rawB =
  from(bucket: "${custom_bucket_name}")
    |> range(start: periodB_start, stop: periodB_stop)
    |> filter(fn:(r)=>r._measurement=="method_timing" and r._field=="duration_ns")

metricsA = buildMetrics(raw: rawA)
metricsB = buildMetrics(raw: rawB)

//------------------------------------------------------------
// 4) Сравнение и расчёт процентов + фактических разниц
//------------------------------------------------------------
diff =
  metricsA
    |> join.inner(
         right: metricsB,
         on: (l,r) => l.class == r.class and l.name == r.name and l.param_types == r.param_types,
         as: (l,r) => ({
             class: l.class,
             name:  l.name,
             param_types: l.param_types,

             // ───────── avg ─────────
             avg_ns_A:   l.avg_ns,
             avg_ns_B:   r.avg_ns,
             avg_ns_diff: r.avg_ns - l.avg_ns,
             avg_ns_pct:  if l.avg_ns == 0.0 then float(v:0)
                          else (r.avg_ns - l.avg_ns) / l.avg_ns * 100.0,

             // ───────── p50 ─────────
             p50_ns_A:   l.p50_ns,
             p50_ns_B:   r.p50_ns,
             p50_ns_diff: r.p50_ns - l.p50_ns,
             p50_ns_pct:  if l.p50_ns == 0.0 then float(v:0)
                          else (r.p50_ns - l.p50_ns) / l.p50_ns * 100.0,

             // ───────── p95 ─────────
             p95_ns_A:   l.p95_ns,
             p95_ns_B:   r.p95_ns,
             p95_ns_diff: r.p95_ns - l.p95_ns,
             p95_ns_pct:  if l.p95_ns == 0.0 then float(v:0)
                          else (r.p95_ns - l.p95_ns) / l.p95_ns * 100.0,

             // ───────── sum ─────────
             sum_ns_A:   l.sum_ns,
             sum_ns_B:   r.sum_ns,
             sum_ns_diff: r.sum_ns - l.sum_ns,
             sum_ns_pct:  if l.sum_ns == 0.0 then float(v:0)
                          else (r.sum_ns - l.sum_ns) / l.sum_ns * 100.0,

             // ───────── max ─────────
             max_ns_A:   l.max_ns,
             max_ns_B:   r.max_ns,
             max_ns_diff: r.max_ns - l.max_ns,
             max_ns_pct:  if l.max_ns == 0.0 then float(v:0)
                          else (r.max_ns - l.max_ns) / l.max_ns * 100.0,

            count_A: l.count,
            count_B: r.count,
         })
       )

//------------------------------------------------------------
// 5) Итоговая таблица
//------------------------------------------------------------
diff
  |> map(fn:(r)=>({
       class_method: string(v:r.class) + "." + string(v:r.name) + string(v:r.param_types),

       count_A: r.count_A, count_B: r.count_B,

       // avg
       avg_ns_A: r.avg_ns_A,  avg_ns_B: r.avg_ns_B,
       avg_ns_diff: r.avg_ns_diff,  avg_ns_pct: r.avg_ns_pct,

       // p50
       p50_ns_A: r.p50_ns_A,  p50_ns_B: r.p50_ns_B,
       p50_ns_diff: r.p50_ns_diff,  p50_ns_pct: r.p50_ns_pct,

       // p95
       p95_ns_A: r.p95_ns_A,  p95_ns_B: r.p95_ns_B,
       p95_ns_diff: r.p95_ns_diff,  p95_ns_pct: r.p95_ns_pct,

       // sum
       sum_ns_A: r.sum_ns_A,  sum_ns_B: r.sum_ns_B,
       sum_ns_diff: r.sum_ns_diff,  sum_ns_pct: r.sum_ns_pct,

       // max
       max_ns_A: r.max_ns_A,  max_ns_B: r.max_ns_B,
       max_ns_diff: r.max_ns_diff,  max_ns_pct: r.max_ns_pct,
     }))
  |> sort(columns: ["avg_ns_pct"], desc: true)
  |> limit(n: 100)
